function ensureThemeSwitcher() {
  if (window.NashitTheme) {
    window.NashitTheme.mount();
    return;
  }

  if (document.querySelector('script[data-theme-switcher="true"]')) {
    return;
  }

  const script = document.createElement("script");
  script.src = `${base}assets/js/theme-switcher.js?v=email-endpoint-1`;
  script.dataset.themeSwitcher = "true";
  script.onload = () => {
    if (window.NashitTheme) {
      window.NashitTheme.mount();
    }
  };
  document.head.appendChild(script);
}

function initNashitNavEvents() {
  const hamburger = document.getElementById("nashitHamburger");
  const navLinks = document.getElementById("nashitNavLinks");

  if (!hamburger || !navLinks) {
    return;
  }

  hamburger.addEventListener("click", () => {
    navLinks.classList.toggle("open");
  });

  navLinks.querySelectorAll("a").forEach((link) => {
    link.addEventListener("click", () => {
      navLinks.classList.remove("open");
    });
  });

  document.addEventListener("click", (event) => {
    if (!hamburger.contains(event.target) && !navLinks.contains(event.target)) {
      navLinks.classList.remove("open");
    }
  });
}

document.addEventListener("DOMContentLoaded", () => {
  const nav = document.getElementById("nav-placeholder");
  const footer = document.getElementById("footer-placeholder");

  if (nav) {
    nav.innerHTML = nashitNavbar;
  }

  if (footer) {
    footer.innerHTML = nashitFooter;
  }

  initNashitNavEvents();
  ensureThemeSwitcher();
});
